static void copyWithBufferSize(Path src, Path dst, int bufferSize) throws IOException {
    try (FileChannel in = FileChannel.open(src, StandardOpenOption.READ);
         FileChannel out = FileChannel.open(dst, StandardOpenOption.WRITE, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
        ByteBuffer buf = ByteBuffer.allocate(bufferSize);
        while (in.read(buf) != -1) {
            buf.flip();
            out.write(buf);
            buf.clear();
        }
    }
}

static int countLinesStreaming(Path p) throws IOException {
    int licznik = 0;
    try (FileChannel ch = FileChannel.open(p, StandardOpenOption.READ)) {
        ByteBuffer buf = ByteBuffer.allocate(512);
        while (ch.read(buf) != -1) {
            buf.flip();
            while (buf.hasRemaining()) {
                if (buf.get() == '\n') licznik++;
            }
            buf.clear();
        }
    }
    return licznik;
}

static void xorTransform(Path p, byte key) throws IOException {
    try (RandomAccessFile raf = new RandomAccessFile(p.toFile(), "rw");
         FileChannel ch = raf.getChannel()) {
        MappedByteBuffer mapped = ch.map(FileChannel.MapMode.READ_WRITE, 0, ch.size());
        for (int i = 0; i < mapped.limit(); i++) {
            byte oryginalny = mapped.get(i);
            mapped.put(i, (byte) (oryginalny ^ key));
        }
    }
}
