static String lookup(Path contentFile, Path indexFile, int targetKey) throws IOException {
    int INDEX_RECORD_SIZE = 16;
    try (FileChannel idxCh = FileChannel.open(indexFile, StandardOpenOption.READ)) {
        long liczbaWpisow = idxCh.size() / INDEX_RECORD_SIZE;
        for (int i = 0; i < liczbaWpisow; i++) {
            ByteBuffer buf = ByteBuffer.allocate(INDEX_RECORD_SIZE);
            idxCh.read(buf, (long) i * INDEX_RECORD_SIZE);
            buf.flip();
            int key = buf.getInt();
            long offset = buf.getLong();
            int length = buf.getInt();
            if (key == targetKey) {
                try (FileChannel contentCh = FileChannel.open(contentFile, StandardOpenOption.READ)) {
                    ByteBuffer dataBuf = ByteBuffer.allocate(length);
                    contentCh.read(dataBuf, offset);
                    dataBuf.flip();
                    byte[] dane = new byte[dataBuf.remaining()];
                    dataBuf.get(dane);
                    return new String(dane, StandardCharsets.UTF_8);
                }
            }
        }
    }
    return null;
}

static class CircularFileWriter {
    private final FileChannel channel;
    private final long maxSize;
    private long position = 0;

    CircularFileWriter(Path p, long maxSize) throws IOException {
        this.channel = FileChannel.open(p, StandardOpenOption.WRITE, StandardOpenOption.CREATE, StandardOpenOption.READ);
        this.maxSize = maxSize;
    }

    void write(byte[] dane) throws IOException {
        if (position + dane.length > maxSize) {
            position = 0; // zawijanie na poczatek
        }
        channel.write(ByteBuffer.wrap(dane), position);
        position += dane.length;
    }
}

