record Person(int id, String name, int age) {}

static class PersonRecordFile implements AutoCloseable {
    private static final int NAME_BYTES = 32, RECORD_SIZE = 4 + NAME_BYTES + 4;
    private final FileChannel channel;

    PersonRecordFile(Path p) throws IOException {
        channel = FileChannel.open(p, StandardOpenOption.READ, StandardOpenOption.WRITE, StandardOpenOption.CREATE);
    }

    void insert(Person person) throws IOException {
        writeAt(channel.size(), person);
    }

    Person readAt(int index) throws IOException {
        ByteBuffer buf = ByteBuffer.allocate(RECORD_SIZE);
        channel.read(buf, (long) index * RECORD_SIZE);
        buf.flip();
        int id = buf.getInt();
        byte[] nameBytes = new byte[NAME_BYTES];
        buf.get(nameBytes);
        int age = buf.getInt();
        return new Person(id, new String(nameBytes, StandardCharsets.UTF_8).strip(), age);
    }

    void updateAt(int index, Person person) throws IOException {
        writeAt((long) index * RECORD_SIZE, person);
    }

    private void writeAt(long offset, Person person) throws IOException {
        ByteBuffer buf = ByteBuffer.allocate(RECORD_SIZE);
        buf.putInt(person.id());
        buf.put(String.format("%-32s", person.name()).getBytes(StandardCharsets.UTF_8), 0, NAME_BYTES);
        buf.putInt(person.age());
        buf.flip();
        channel.write(buf, offset);
    }

    public void close() throws IOException { channel.close(); }
}
